VFORMS.zh=["Doing now (在…)","Did it (…了)","Not (不…)","Want to (想…)","Please (请…)"];
VERBS.zh=[{"d": "去", "r": "qù", "en": "to go", "irr": "Chinese verbs never change form. For \"didn't go\", use 没 instead of 不: 没去 (méi qù).", "f": {"a": null, "b": ["去了", "qù le"], "c": ["不去", "bú qù"], "d": ["想去", "xiǎng qù"], "e": null}, "ex": ["我们明天去仁川", "wǒmen míngtiān qù Rénchuān", "We're going to Incheon tomorrow"], "pr": "chew", "trip": true}, {"d": "来", "r": "lái", "en": "to come", "irr": "", "f": {"a": null, "b": ["来了", "lái le"], "c": ["不来", "bù lái"], "d": ["想来", "xiǎng lái"], "e": ["请来", "qǐng lái"]}, "ex": ["他来了", "tā lái le", "He's here (he has come)"], "pr": "lie", "trip": false}, {"d": "吃", "r": "chī", "en": "to eat", "irr": "请吃 is what a host says to offer you food.", "f": {"a": ["在吃", "zài chī"], "b": ["吃了", "chī le"], "c": ["不吃", "bù chī"], "d": ["想吃", "xiǎng chī"], "e": ["请吃", "qǐng chī"]}, "ex": ["我想吃炸酱面", "wǒ xiǎng chī zhájiàngmiàn", "I want to eat jajangmyeon"], "pr": "chrr", "trip": true}, {"d": "喝", "r": "hē", "en": "to drink", "irr": "", "f": {"a": ["在喝", "zài hē"], "b": ["喝了", "hē le"], "c": ["不喝", "bù hē"], "d": ["想喝", "xiǎng hē"], "e": ["请喝", "qǐng hē"]}, "ex": ["我们喝啤酒吧", "wǒmen hē píjiǔ ba", "Let's drink beer"], "pr": "huh", "trip": true}, {"d": "看", "r": "kàn", "en": "to look / watch / read", "irr": "", "f": {"a": ["在看", "zài kàn"], "b": ["看了", "kàn le"], "c": ["不看", "bú kàn"], "d": ["想看", "xiǎng kàn"], "e": ["请看", "qǐng kàn"]}, "ex": ["请看这个", "qǐng kàn zhège", "Please look at this"], "pr": "kahn", "trip": false}, {"d": "买", "r": "mǎi", "en": "to buy", "irr": "", "f": {"a": ["在买", "zài mǎi"], "b": ["买了", "mǎi le"], "c": ["不买", "bù mǎi"], "d": ["想买", "xiǎng mǎi"], "e": null}, "ex": ["我想买这个", "wǒ xiǎng mǎi zhège", "I want to buy this"], "pr": "my", "trip": true}, {"d": "坐", "r": "zuò", "en": "to sit / ride (a vehicle)", "irr": "坐 is also \"to take\" a bus, train or plane.", "f": {"a": null, "b": ["坐了", "zuò le"], "c": ["不坐", "bú zuò"], "d": ["想坐", "xiǎng zuò"], "e": ["请坐", "qǐng zuò"]}, "ex": ["我们坐地铁去", "wǒmen zuò dìtiě qù", "We'll go by subway"], "pr": "dzwaw", "trip": true}, {"d": "说", "r": "shuō", "en": "to speak / say", "irr": "", "f": {"a": ["在说", "zài shuō"], "b": ["说了", "shuō le"], "c": ["不说", "bù shuō"], "d": ["想说", "xiǎng shuō"], "e": ["请说", "qǐng shuō"]}, "ex": ["请说慢一点", "qǐng shuō màn yìdiǎn", "Please speak a bit slower"], "pr": "shwaw", "trip": false}, {"d": "有", "r": "yǒu", "en": "to have / there is", "irr": "The negative is always 没有 (méiyǒu), never 不有.", "f": {"a": null, "b": ["有了", "yǒu le"], "c": ["没有", "méiyǒu"], "d": null, "e": null}, "ex": ["有英文菜单吗？", "yǒu Yīngwén càidān ma?", "Is there an English menu?"], "pr": "yoh", "trip": true}, {"d": "是", "r": "shì", "en": "to be (am / is / are)", "irr": "Only the negative changes: 不是 (bú shì). There's no 了 or 在 form.", "f": {"a": null, "b": null, "c": ["不是", "bú shì"], "d": null, "e": null}, "ex": ["我是美国人", "wǒ shì Měiguó rén", "I'm American"], "pr": "shrr", "trip": false}, {"d": "找", "r": "zhǎo", "en": "to look for", "irr": "找到了 = found it. At a till, 找 also means \"to give change\".", "f": {"a": ["在找", "zài zhǎo"], "b": ["找到了", "zhǎodào le"], "c": ["不找", "bù zhǎo"], "d": ["想找", "xiǎng zhǎo"], "e": null}, "ex": ["我在找地铁站", "wǒ zài zhǎo dìtiě zhàn", "I'm looking for the subway station"], "pr": "jaow", "trip": true}, {"d": "住", "r": "zhù", "en": "to stay / live", "irr": "", "f": {"a": null, "b": ["住了", "zhù le"], "c": ["不住", "bú zhù"], "d": ["想住", "xiǎng zhù"], "e": null}, "ex": ["我住在明洞", "wǒ zhù zài Míngdòng", "I'm staying in Myeongdong"], "pr": "joo", "trip": true}, {"d": "等", "r": "děng", "en": "to wait", "irr": "请等一下 = please wait a moment.", "f": {"a": ["在等", "zài děng"], "b": ["等了", "děng le"], "c": ["不等", "bù děng"], "d": null, "e": ["请等一下", "qǐng děng yíxià"]}, "ex": ["我在等朋友", "wǒ zài děng péngyou", "I'm waiting for a friend"], "pr": "dung", "trip": true}, {"d": "帮", "r": "bāng", "en": "to help", "irr": "", "f": {"a": ["在帮", "zài bāng"], "b": ["帮了", "bāng le"], "c": ["不帮", "bù bāng"], "d": ["想帮", "xiǎng bāng"], "e": ["请帮我", "qǐng bāng wǒ"]}, "ex": ["可以帮我吗？", "kěyǐ bāng wǒ ma?", "Can you help me?"], "pr": "bahng", "trip": true}, {"d": "走", "r": "zǒu", "en": "to walk / leave", "irr": "走了 often means \"has left\".", "f": {"a": ["在走", "zài zǒu"], "b": ["走了", "zǒu le"], "c": ["不走", "bù zǒu"], "d": ["想走", "xiǎng zǒu"], "e": ["请走这边", "qǐng zǒu zhèbiān"]}, "ex": ["我们走吧", "wǒmen zǒu ba", "Let's go"], "pr": "dzoh", "trip": true}, {"d": "拍", "r": "pāi", "en": "to take (a photo)", "irr": "拍照 (pāizhào) = take a photo.", "f": {"a": ["在拍", "zài pāi"], "b": ["拍了", "pāi le"], "c": ["不拍", "bù pāi"], "d": ["想拍", "xiǎng pāi"], "e": ["请拍", "qǐng pāi"]}, "ex": ["可以拍照吗？", "kěyǐ pāizhào ma?", "May I take a photo?"], "pr": "pie", "trip": true}, {"d": "换", "r": "huàn", "en": "to change / exchange", "irr": "", "f": {"a": ["在换", "zài huàn"], "b": ["换了", "huàn le"], "c": ["不换", "bú huàn"], "d": ["想换", "xiǎng huàn"], "e": ["请换", "qǐng huàn"]}, "ex": ["我想换钱", "wǒ xiǎng huàn qián", "I want to exchange money"], "pr": "hwahn", "trip": true}, {"d": "睡觉", "r": "shuìjiào", "en": "to sleep", "irr": "", "f": {"a": ["在睡觉", "zài shuìjiào"], "b": ["睡觉了", "shuìjiào le"], "c": ["不睡觉", "bú shuìjiào"], "d": ["想睡觉", "xiǎng shuìjiào"], "e": null}, "ex": ["我很累，想睡觉", "wǒ hěn lèi, xiǎng shuìjiào", "I'm tired and want to sleep"], "pr": "shway-jyow", "trip": false}, {"d": "知道", "r": "zhīdào", "en": "to know (a fact)", "irr": "知道了 = \"got it / understood\".", "f": {"a": null, "b": ["知道了", "zhīdào le"], "c": ["不知道", "bù zhīdào"], "d": null, "e": null}, "ex": ["我不知道", "wǒ bù zhīdào", "I don't know"], "pr": "jrr-daow", "trip": false}, {"d": "懂", "r": "dǒng", "en": "to understand", "irr": "", "f": {"a": null, "b": ["懂了", "dǒng le"], "c": ["不懂", "bù dǒng"], "d": null, "e": null}, "ex": ["我听不懂", "wǒ tīng bu dǒng", "I don't understand (what I hear)"], "pr": "dong", "trip": false}, {"d": "学", "r": "xué", "en": "to study / learn", "irr": "", "f": {"a": ["在学", "zài xué"], "b": ["学了", "xué le"], "c": ["不学", "bù xué"], "d": ["想学", "xiǎng xué"], "e": null}, "ex": ["我在学中文", "wǒ zài xué Zhōngwén", "I'm learning Chinese"], "pr": "shweh", "trip": false}, {"d": "开", "r": "kāi", "en": "to open / drive", "irr": "", "f": {"a": ["在开", "zài kāi"], "b": ["开了", "kāi le"], "c": ["不开", "bù kāi"], "d": ["想开", "xiǎng kāi"], "e": ["请开", "qǐng kāi"]}, "ex": ["几点开门？", "jǐ diǎn kāimén?", "What time do you open?"], "pr": "kai", "trip": false}, {"d": "玩", "r": "wán", "en": "to have fun / hang out", "irr": "", "f": {"a": ["在玩", "zài wán"], "b": ["玩了", "wán le"], "c": ["不玩", "bù wán"], "d": ["想玩", "xiǎng wán"], "e": null}, "ex": ["我们去东京玩", "wǒmen qù Dōngjīng wán", "We're going to Tokyo for fun"], "pr": "wahn", "trip": true}, {"d": "用", "r": "yòng", "en": "to use", "irr": "不用 also means \"no need\": 不用谢 = no need to thank me.", "f": {"a": ["在用", "zài yòng"], "b": ["用了", "yòng le"], "c": ["不用", "bú yòng"], "d": ["想用", "xiǎng yòng"], "e": ["请用", "qǐng yòng"]}, "ex": ["可以用卡吗？", "kěyǐ yòng kǎ ma?", "Can I use a card?"], "pr": "yong", "trip": true}];
WORDS.zh=[{"k": "food", "n": "🍜 Food", "w": [{"nat": "炸酱面", "kana": "", "rom": "zhájiàngmiàn", "en": "black-bean noodles (jajangmyeon)", "pr": "jah-jyahng-myen", "note": "Korean 짜장면 (jjajangmyeon) grew out of this northern Chinese dish. Korea's version uses sweet black chunjang sauce; the mainland one is saltier, browner and not sweet. Incheon Chinatown is called its Korean birthplace (Jjajangmyeon Museum).", "trip": true}, {"nat": "糖醋肉", "kana": "", "rom": "tángcùròu", "en": "sweet and sour pork (tangsuyuk)", "pr": "tahng-tsoo-roh", "note": "Korean 탕수육 (tangsuyuk): crisp fried pork with a thick sweet-sour sauce, poured on or served on the side.", "trip": true}, {"nat": "炒码面", "kana": "", "rom": "chǎomǎmiàn", "en": "spicy seafood noodle soup (jjamppong)", "pr": "chaow-mah-myen", "note": "⚠️ Korean 짬뽕 (jjamppong) has no exact mainland match. Korean-Chinese menus sometimes write 炒码面; in China, 海鲜面 (seafood noodles) is closest but usually not spicy.", "trip": true}, {"nat": "干烹鸡", "kana": "", "rom": "gānpēngjī", "en": "sweet-spicy fried chicken (kkanpunggi)", "pr": "gahn-pung-jee", "note": "Korean 깐풍기 (kkanpunggi), a Korean-Chinese favorite.", "trip": true}, {"nat": "煎饺", "kana": "", "rom": "jiānjiǎo", "en": "pan-fried dumplings (gun-mandu)", "pr": "jyen-jyaow", "note": "Closest to Korean-Chinese 군만두 (gun-mandu). Boiled dumplings are 饺子 (jiǎozi).", "trip": true}, {"nat": "月饼", "kana": "", "rom": "yuèbǐng", "en": "mooncake", "pr": "yweh-bing", "note": "Incheon Chinatown bakeries sell these year-round.", "trip": true}, {"nat": "饺子", "kana": "", "rom": "jiǎozi", "en": "dumplings (boiled)", "pr": "jyaow-dzuh", "note": "", "trip": false}, {"nat": "包子", "kana": "", "rom": "bāozi", "en": "steamed bun", "pr": "baow-dzuh", "note": "", "trip": false}, {"nat": "米饭", "kana": "", "rom": "mǐfàn", "en": "cooked rice", "pr": "mee-fahn", "note": "", "trip": false}, {"nat": "面条", "kana": "", "rom": "miàntiáo", "en": "noodles", "pr": "myen-tyow", "note": "", "trip": false}, {"nat": "炒饭", "kana": "", "rom": "chǎofàn", "en": "fried rice", "pr": "chaow-fahn", "note": "Korean-Chinese fried rice often comes with black-bean sauce on the side.", "trip": false}, {"nat": "烤鸭", "kana": "", "rom": "kǎoyā", "en": "roast duck", "pr": "kaow-yah", "note": "", "trip": false}, {"nat": "茶", "kana": "", "rom": "chá", "en": "tea", "pr": "chah", "note": "", "trip": false}, {"nat": "啤酒", "kana": "", "rom": "píjiǔ", "en": "beer", "pr": "pee-jyoh", "note": "", "trip": false}, {"nat": "鸡肉", "kana": "", "rom": "jīròu", "en": "chicken (meat)", "pr": "jee-roh", "note": "", "trip": false}, {"nat": "猪肉", "kana": "", "rom": "zhūròu", "en": "pork", "pr": "joo-roh", "note": "", "trip": false}, {"nat": "牛肉", "kana": "", "rom": "niúròu", "en": "beef", "pr": "nyoh-roh", "note": "", "trip": false}, {"nat": "海鲜", "kana": "", "rom": "hǎixiān", "en": "seafood", "pr": "hai-shyen", "note": "", "trip": false}, {"nat": "醋", "kana": "", "rom": "cù", "en": "vinegar", "pr": "tsoo", "note": "Koreans dip gun-mandu in soy sauce mixed with vinegar.", "trip": false}]}, {"k": "transport", "n": "🚆 Transport", "w": [{"nat": "地铁", "kana": "", "rom": "dìtiě", "en": "subway", "pr": "dee-tyeh", "note": "", "trip": false}, {"nat": "公交车", "kana": "", "rom": "gōngjiāochē", "en": "bus", "pr": "gong-jyaow-chuh", "note": "", "trip": false}, {"nat": "出租车", "kana": "", "rom": "chūzūchē", "en": "taxi", "pr": "choo-dzoo-chuh", "note": "", "trip": false}, {"nat": "火车", "kana": "", "rom": "huǒchē", "en": "train", "pr": "hwaw-chuh", "note": "", "trip": false}, {"nat": "高铁", "kana": "", "rom": "gāotiě", "en": "high-speed train", "pr": "gaow-tyeh", "note": "", "trip": false}, {"nat": "新干线", "kana": "", "rom": "xīngànxiàn", "en": "Shinkansen", "pr": "sheen-gahn-shyen", "note": "Japan's bullet train.", "trip": true}, {"nat": "机场", "kana": "", "rom": "jīchǎng", "en": "airport", "pr": "jee-chahng", "note": "", "trip": true}, {"nat": "票", "kana": "", "rom": "piào", "en": "ticket", "pr": "pyow", "note": "", "trip": false}, {"nat": "出口", "kana": "", "rom": "chūkǒu", "en": "exit", "pr": "choo-koh", "note": "Station exits are numbered: 3号出口 = Exit 3.", "trip": false}, {"nat": "入口", "kana": "", "rom": "rùkǒu", "en": "entrance", "pr": "roo-koh", "note": "", "trip": false}, {"nat": "站", "kana": "", "rom": "zhàn", "en": "station / stop", "pr": "jahn", "note": "", "trip": false}, {"nat": "行李", "kana": "", "rom": "xíngli", "en": "luggage", "pr": "shing-lee", "note": "", "trip": false}]}, {"k": "places", "n": "🏙️ Places", "w": [{"nat": "唐人街", "kana": "", "rom": "tángrénjiē", "en": "Chinatown", "pr": "tahng-run-jyeh", "note": "Incheon's is usually called 仁川中华街 (Rénchuān Zhōnghuá Jiē).", "trip": true}, {"nat": "仁川", "kana": "", "rom": "Rénchuān", "en": "Incheon", "pr": "run-chwahn", "note": "", "trip": true}, {"nat": "首尔", "kana": "", "rom": "Shǒu'ěr", "en": "Seoul", "pr": "shoh-ar", "note": "", "trip": true}, {"nat": "明洞", "kana": "", "rom": "Míngdòng", "en": "Myeongdong", "pr": "ming-dong", "note": "", "trip": true}, {"nat": "东京", "kana": "", "rom": "Dōngjīng", "en": "Tokyo", "pr": "dong-jing", "note": "", "trip": true}, {"nat": "大阪", "kana": "", "rom": "Dàbǎn", "en": "Osaka", "pr": "dah-bahn", "note": "", "trip": true}, {"nat": "热海", "kana": "", "rom": "Rèhǎi", "en": "Atami", "pr": "ruh-hai", "note": "Same characters as Japanese 熱海, read the Chinese way.", "trip": true}, {"nat": "厕所", "kana": "", "rom": "cèsuǒ", "en": "toilet", "pr": "tsuh-swaw", "note": "", "trip": false}, {"nat": "便利店", "kana": "", "rom": "biànlìdiàn", "en": "convenience store", "pr": "byen-lee-dyen", "note": "", "trip": false}, {"nat": "银行", "kana": "", "rom": "yínháng", "en": "bank", "pr": "yeen-hahng", "note": "", "trip": false}, {"nat": "酒店", "kana": "", "rom": "jiǔdiàn", "en": "hotel", "pr": "jyoh-dyen", "note": "", "trip": false}, {"nat": "餐厅", "kana": "", "rom": "cāntīng", "en": "restaurant", "pr": "tsahn-ting", "note": "", "trip": false}, {"nat": "寺庙", "kana": "", "rom": "sìmiào", "en": "temple", "pr": "suh-myow", "note": "", "trip": false}, {"nat": "温泉", "kana": "", "rom": "wēnquán", "en": "hot spring (onsen)", "pr": "wun-chwen", "note": "", "trip": true}, {"nat": "博物馆", "kana": "", "rom": "bówùguǎn", "en": "museum", "pr": "baw-woo-gwahn", "note": "", "trip": false}]}, {"k": "shopping", "n": "🛍️ Shopping", "w": [{"nat": "钱", "kana": "", "rom": "qián", "en": "money", "pr": "chyen", "note": "", "trip": false}, {"nat": "现金", "kana": "", "rom": "xiànjīn", "en": "cash", "pr": "shyen-jeen", "note": "", "trip": false}, {"nat": "信用卡", "kana": "", "rom": "xìnyòngkǎ", "en": "credit card", "pr": "sheen-yong-kah", "note": "", "trip": false}, {"nat": "收据", "kana": "", "rom": "shōujù", "en": "receipt", "pr": "shoh-jew", "note": "", "trip": false}, {"nat": "袋子", "kana": "", "rom": "dàizi", "en": "bag", "pr": "dai-dzuh", "note": "", "trip": false}, {"nat": "免税", "kana": "", "rom": "miǎnshuì", "en": "tax-free", "pr": "myen-shway", "note": "Shops in Korea and Japan often show 免税 / Tax Free signs.", "trip": true}, {"nat": "衣服", "kana": "", "rom": "yīfu", "en": "clothes", "pr": "ee-foo", "note": "", "trip": false}, {"nat": "鞋", "kana": "", "rom": "xié", "en": "shoes", "pr": "shyeh", "note": "", "trip": false}, {"nat": "礼物", "kana": "", "rom": "lǐwù", "en": "gift", "pr": "lee-woo", "note": "", "trip": false}, {"nat": "尺码", "kana": "", "rom": "chǐmǎ", "en": "size", "pr": "chrr-mah", "note": "", "trip": false}]}, {"k": "health", "n": "🚑 Health & safety", "w": [{"nat": "药", "kana": "", "rom": "yào", "en": "medicine", "pr": "yow", "note": "", "trip": false}, {"nat": "头疼", "kana": "", "rom": "tóuténg", "en": "headache", "pr": "toh-tung", "note": "", "trip": false}, {"nat": "感冒", "kana": "", "rom": "gǎnmào", "en": "a cold", "pr": "gahn-maow", "note": "", "trip": false}, {"nat": "医生", "kana": "", "rom": "yīshēng", "en": "doctor", "pr": "ee-shung", "note": "", "trip": false}, {"nat": "护照", "kana": "", "rom": "hùzhào", "en": "passport", "pr": "hoo-jaow", "note": "", "trip": true}, {"nat": "手机", "kana": "", "rom": "shǒujī", "en": "cell phone", "pr": "shoh-jee", "note": "", "trip": false}, {"nat": "创可贴", "kana": "", "rom": "chuāngkětiē", "en": "adhesive bandage", "pr": "chwahng-kuh-tyeh", "note": "", "trip": false}]}];
